import { useState, useEffect, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Save, X } from "lucide-react";
import {
  LABOR_SERVICE_CATEGORY_FIELDS,
  LABOR_SERVICE_CATEGORY_FIELD_NAMES,
} from "./laborServiceCategorySchema";
import { expectedEntityFields, replaceEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { createInventoryRecordWithRecovery, recordInventoryCostChanges, loadInventoryCostHistory } from "./inventoryPersistence";
import { inventoryNumberInput } from "./inventoryNormalization";

/**
 * Generic inventory add/edit modal driven by a `source` config object.
 */
export default function InventoryFormModal({ source, editingItem, onCancel, onSaved }) {
  const [formData, setFormData] = useState({});
  const [saving, setSaving] = useState(false);
  const [costHistory, setCostHistory] = useState([]);
  const saveRef = useRef(false);

  // Is this the Labor & Services source? If so we drive category-specific
  // fields from the per-category schema below.
  const isLaborServices = source?.key === "labor_services";
  const currentCategory = formData.service_category || "";
  const categorySchema = isLaborServices ? LABOR_SERVICE_CATEGORY_FIELDS[currentCategory] : null;

  // Initialize form whenever the modal opens / source changes
  useEffect(() => {
    const initial = {};
    source.fields.forEach((f) => {
      // Priority: existing row value → source.defaults → boolean false / blank.
      const fromDefaults = source.defaults?.[f.name];
      initial[f.name] = editingItem?.[f.name] ?? fromDefaults ?? (f.type === "boolean" ? false : "");
    });
    // Pre-fill category-specific fields too (so editing an existing row shows
    // its saved values for every category-owned field).
    if (source?.key === "labor_services") {
      LABOR_SERVICE_CATEGORY_FIELD_NAMES.forEach((name) => {
        if (initial[name] === undefined) {
          initial[name] = editingItem?.[name] ?? "";
        }
      });
    }
    setFormData(initial);
  }, [source, editingItem]);

  useEffect(() => {
    if (!editingItem?.id) { setCostHistory([]); return; }
    let active = true;
    loadInventoryCostHistory({ itemId: editingItem.id, entityKey: source?.key || "" })
      .then((rows) => active && setCostHistory(rows))
      .catch(() => {});
    return () => { active = false; };
  }, [editingItem?.id, source?.key]);

  const update = (name, value) => {
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (saveRef.current) return;

    // Required check
    for (const f of source.fields) {
      if (f.required) {
        const v = formData[f.name];
        if (v === undefined || v === null || String(v).trim() === "") {
          alert(`Please fill in "${f.label}"`);
          return;
        }
      }
    }

    // Coerce types — for the base fields AND (if Labor & Services) the
    // category-specific fields for the SELECTED category only. Fields owned by
    // other categories are left untouched so switching categories doesn't wipe
    // historical data, but we don't write empty values for them either.
    // Number coercion is the boundary's catalog draft (CMP-A08): blank → null
    // ("not cataloged"), numeric → Number, anything else stays VERBATIM so the
    // availability checks report it — the old parseFloat partial-parsed
    // "12abc" into 12 and minted NaN for "abc".
    const payload = {};
    const coerce = (f, v) => {
      if (f.type === "number") {
        return v === "" || v === null || v === undefined ? null : inventoryNumberInput(v);
      }
      if (f.type === "boolean") return !!v;
      return v ?? "";
    };

    source.fields.forEach((f) => { payload[f.name] = coerce(f, formData[f.name]); });

    if (isLaborServices && categorySchema) {
      categorySchema.fields.forEach((f) => {
        payload[f.name] = coerce(f, formData[f.name]);
      });
    }

    // Apply source-level defaults for fields not in the form schema (e.g.
    // `material_type: "pole"` for the Poles sub-tab — needed for entity
    // categorization but not user-editable).
    if (source.defaults) {
      Object.entries(source.defaults).forEach(([k, v]) => {
        if (payload[k] === undefined || payload[k] === "" || payload[k] === null) {
          payload[k] = v;
        }
      });
    }

    saveRef.current = true;
    setSaving(true);
    try {
      if (editingItem?.id) {
        const live = await source.entity.get(editingItem.id);
        if (
          editingItem.updated_date &&
          live?.updated_date &&
          editingItem.updated_date !== live.updated_date
        ) {
          alert("This inventory item changed in another session. Your changes were not saved. The inventory list will reload so you can review the latest record before editing again.");
          onSaved?.();
          return;
        }
        await replaceEntityFieldsIfUnchanged({
          entity: source.entity,
          id: editingItem.id,
          expectedUpdatedAt: live.updated_date || "",
          expectedFields: expectedEntityFields(live, payload),
          nextFields: payload,
          label: `${source.label || "Inventory"} item`,
        });
        await recordInventoryCostChanges({
          itemId: editingItem.id,
          entityKey: source?.key || "",
          before: live,
          after: payload,
          fields: source.fields || [],
          note: `${source.label || "Inventory"} item edit`,
        });
      } else {
        await createInventoryRecordWithRecovery({
          entity: source.entity,
          data: payload,
          nameField: source.nameField,
          label: `${source.label || "Inventory"} item`,
        });
      }
      onSaved?.();
    } catch (err) {
      console.error("Save failed:", err);
      alert(err?.message || "Error saving item. Please try again.");
    } finally {
      saveRef.current = false;
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <Card className="bg-white w-full max-w-3xl max-h-[90vh] overflow-y-auto">
        <CardHeader className="border-b sticky top-0 bg-white z-10">
          <div className="flex justify-between items-center">
            <CardTitle className="flex items-center gap-2">
              {source.icon && <source.icon className={`w-5 h-5 ${source.color}`} />}
              {editingItem?.id ? "Edit" : "Add"} {source.label}
            </CardTitle>
            <Button variant="ghost" size="icon" onClick={onCancel} disabled={saving}>
              <X className="w-4 h-4" />
            </Button>
          </div>
        </CardHeader>
        <CardContent className="pt-6">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid md:grid-cols-2 gap-4">
              {source.fields.map((f) => {
                if (f.type === "textarea") return null; // render full-width below

                // Conditional visibility based on another field's value (e.g. service_category)
                if (f.showIfCategory) {
                  const cat = formData.service_category || formData.category || "";
                  if (cat !== f.showIfCategory) return null;
                }
                if (f.showIfNotCategory) {
                  const cat = formData.service_category || formData.category || "";
                  if (cat === f.showIfNotCategory) return null;
                }

                return (
                  <div key={f.name} className={f.type === "boolean" ? "md:col-span-2 flex items-center gap-3 pt-2" : ""}>
                    {f.type !== "boolean" && (
                      <Label className="text-slate-700">
                        {f.label} {f.required && <span className="text-red-500">*</span>}
                      </Label>
                    )}
                    {f.type === "select" && (
                      <Select
                        value={formData[f.name] || ""}
                        onValueChange={(v) => update(f.name, v)}
                      >
                        <SelectTrigger className="mt-1">
                          <SelectValue placeholder="Select..." />
                        </SelectTrigger>
                        <SelectContent>
                          {f.options.map((o) => (
                            <SelectItem key={o} value={o}>
                              {String(o)
                                .replace(/_/g, " ")
                                .replace(/\b\w/g, (c) => c.toUpperCase())}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                    {f.type === "text" && (
                      <Input
                        value={formData[f.name] || ""}
                        onChange={(e) => update(f.name, e.target.value)}
                        placeholder={f.placeholder}
                        className="mt-1"
                      />
                    )}
                    {f.type === "number" && (
                      <Input
                        type="number"
                        step="any"
                        value={formData[f.name] ?? ""}
                        onChange={(e) => update(f.name, e.target.value)}
                        placeholder={f.placeholder}
                        className="mt-1"
                      />
                    )}
                    {f.type === "boolean" && (
                      <>
                        <Switch
                          checked={!!formData[f.name]}
                          onCheckedChange={(v) => update(f.name, v)}
                        />
                        <Label className="text-slate-700">{f.label}</Label>
                      </>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Category-specific section (Labor & Services only) */}
            {isLaborServices && categorySchema && (
              <div className="border-t pt-4 mt-2">
                <h3 className="font-semibold text-slate-900 mb-3 flex items-center gap-2">
                  <span className="inline-block w-1 h-4 bg-emerald-500 rounded-full" />
                  {categorySchema.label}
                </h3>
                <div className="grid md:grid-cols-2 gap-4">
                  {categorySchema.fields.map((f) => (
                    <div key={f.name} className={f.type === "boolean" ? "md:col-span-2 flex items-center gap-3 pt-2" : ""}>
                      {f.type !== "boolean" && (
                        <Label className="text-slate-700">{f.label}</Label>
                      )}
                      {f.type === "select" && (
                        <Select
                          value={formData[f.name] || ""}
                          onValueChange={(v) => update(f.name, v)}
                        >
                          <SelectTrigger className="mt-1">
                            <SelectValue placeholder="Select..." />
                          </SelectTrigger>
                          <SelectContent>
                            {f.options.map((o) => (
                              <SelectItem key={o} value={o}>
                                {String(o)
                                  .replace(/_/g, " ")
                                  .replace(/\b\w/g, (c) => c.toUpperCase())}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      )}
                      {f.type === "text" && (
                        <Input
                          value={formData[f.name] || ""}
                          onChange={(e) => update(f.name, e.target.value)}
                          className="mt-1"
                        />
                      )}
                      {f.type === "number" && (
                        <Input
                          type="number"
                          step="any"
                          value={formData[f.name] ?? ""}
                          onChange={(e) => update(f.name, e.target.value)}
                          className="mt-1"
                        />
                      )}
                      {f.type === "boolean" && (
                        <>
                          <Switch
                            checked={!!formData[f.name]}
                            onCheckedChange={(v) => update(f.name, v)}
                          />
                          <Label className="text-slate-700">{f.label}</Label>
                        </>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Full-width textareas */}
            {source.fields.filter((f) => f.type === "textarea").map((f) => (
              <div key={f.name}>
                <Label className="text-slate-700">{f.label}</Label>
                <Textarea
                  value={formData[f.name] || ""}
                  onChange={(e) => update(f.name, e.target.value)}
                  className="mt-1 h-20"
                />
              </div>
            ))}

            {editingItem?.id && costHistory.length > 0 && (
              <div className="pt-4 border-t">
                <p className="text-xs font-semibold text-slate-500 mb-1.5">Cost history</p>
                <ul className="text-xs text-slate-600 space-y-1">
                  {costHistory.map((h, i) => (
                    <li key={h.id || i} className="flex justify-between gap-3">
                      <span>{String(h.cost_field || "").replace(/_/g, " ")} — ${Number(h.old_cost || 0).toFixed(2)} → ${Number(h.new_cost || 0).toFixed(2)}</span>
                      <span className="text-slate-400 whitespace-nowrap">{String(h.created_date || "").slice(0, 10)}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            <div className="flex justify-end gap-3 pt-4 border-t">
              <Button type="button" variant="outline" onClick={onCancel} disabled={saving}>
                Cancel
              </Button>
              <Button type="submit" disabled={saving} className="bg-blue-600 hover:bg-blue-700">
                <Save className="w-4 h-4 mr-2" />
                {saving ? "Saving..." : editingItem ? "Update" : "Add"} Item
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
